# -*- coding: utf-8 -*-
# (speaker, italiano, coreano); speaker None => didascalia, "#" => titolo di scena (nessuno dei due conta come battuta)
F, R, AM, CA, M, L, HE = "Filippo", "Renzo", "Mancini", "Cappelli", "Matteo", "Lorenzo", "Hélène"
D = [
("#", "Scena 1 — Martedì 27 maggio, ore 8.30. In macchina, da Scandicci a Firenze.", "장면 1 — 5월 27일 화요일 오전 8시 30분. 스칸디치에서 피렌체로 가는 차 안."),
(None, "Filippo guida. Renzo, sul sedile accanto, tiene sulle ginocchia un pacco di cartone grigio ancora chiuso, avvolto in un sacchetto di plastica trasparente. Sopra, un'etichetta scritta a mano da Giulia: «NON APRIRE. PROVA.»", "필리포가 운전한다. 옆자리의 렌초는 아직 뜯지 않은 회색 골판지 상자를 무릎에 올려놓고 있다. 투명 비닐봉지로 싼 상자 위에는 줄리아가 손으로 쓴 라벨. '열지 마시오. 증거.'"),
(R, "Pesa poco. Una borsa di pelle vera, col fondo da un millimetro e otto, pesa il doppio.", "가볍네. 진짜 가죽 가방이면, 바닥이 1.8밀리짜리면 두 배는 나가지."),
(F, "Non l'hai aperta, vero?", "열어 보진 않았지?"),
(R, "Filippo, ho settantadue anni. Se dico che non l'ho aperta, non l'ho aperta. L'ho soltanto tenuta in mano.", "필리포, 나 일흔둘이야. 안 열었다면 안 연 거지. 손에 들어 보기만 했어."),
(F, "Scusa. Stanotte ho dormito tre ore.", "미안해. 어젯밤에 세 시간 잤어."),
(R, "Per la borsa o per altro?", "가방 때문이냐, 다른 거 때문이냐?"),
(F, "Per la borsa.", "가방 때문이지."),
(None, "Il telefono di Filippo vibra nel portaoggetti. Sul display: un numero francese. Filippo lo guarda e lascia che smetta da solo.", "필리포의 휴대폰이 수납칸에서 진동한다. 화면에 프랑스 번호가 뜬다. 필리포는 그것을 바라보다가 저절로 멈출 때까지 내버려 둔다."),
(R, "Non rispondi?", "안 받아?"),
(F, "Guido. E poi è presto.", "운전 중이잖아. 그리고 아직 이르고."),
(R, "A Parigi è la stessa ora che qui.", "파리도 여기랑 같은 시간인데."),
(F, "Renzo.", "렌초."),
(R, "Va bene, va bene. Io cucio, non chiedo. Me l'ha insegnato tuo nonno.", "알았어, 알았어. 난 바느질만 하지 묻지 않아. 네 할아버지한테 배운 거야."),
(F, "Senti, quando siamo lì, lascia parlare l'avvocato. Tu parli solo se ti fanno una domanda.", "들어 봐, 거기 가면 변호사님이 말하게 둬. 질문받을 때만 말해."),
(R, "E se il maresciallo mi chiede della colla?", "원사가 본드에 대해 물으면?"),
(F, "Allora parli della colla. Di tutto quello che vuoi, purché sia sulla borsa.", "그럼 본드 얘기를 해. 가방에 관한 거라면 뭐든."),
(R, "Sulla borsa ho da dire parecchio.", "가방에 대해선 할 말이 많지."),
(F, "Lo so. Per questo ti ho portato.", "알아. 그래서 데려온 거야."),

("#", "Scena 2 — Ore 9.30. Comando della Guardia di Finanza, Firenze. Un ufficio al primo piano.", "장면 2 — 오전 9시 30분. 피렌체 재무경찰 본부. 2층의 한 사무실."),
(None, "Una scrivania di metallo, una bandiera italiana, un computer con lo schermo girato verso il visitatore. Il maresciallo Sergio Cappelli, sui cinquant'anni, ha la divisa grigia e un accento lucchese che non prova a nascondere. L'avvocato Mancini è già seduto.", "철제 책상, 이탈리아 국기, 방문객 쪽으로 화면을 돌려 둔 컴퓨터. 쉰 살 안팎의 세르조 카펠리 원사는 회색 제복 차림에, 숨길 생각이 없는 루카 억양을 쓴다. 만치니 변호사는 이미 앉아 있다."),
(CA, "Buongiorno. Prego, si accomodino. L'avvocato mi ha già anticipato la questione al telefono. Il signor Corsini?", "안녕하세요. 앉으시죠. 변호사님이 전화로 미리 말씀해 주셨습니다. 코르시니 씨죠?"),
(F, "Filippo Corsini, direttore generale della Pelletteria Corsini. Lui è Renzo Paoli, il nostro maestro pellettiere.", "펠레테리아 코르시니 총괄 사장 필리포 코르시니입니다. 이쪽은 저희 가죽 장인 렌초 파올리고요."),
(CA, "Piacere. Allora, signor Corsini, per quanto riguarda la denuncia, mi servono tre cose: chi siete, che cosa vi hanno copiato, e da quando ve ne siete accorti.", "반갑습니다. 자, 코르시니 씨, 고소와 관련해서 세 가지가 필요합니다. 누구신지, 무엇을 베꼈는지, 그리고 언제 알게 되셨는지."),
(AM, "Ho preparato una cartella, maresciallo. Il marchio «Corsini 1958», registrato in Italia; il deposito internazionale di «Corsini Scandicci»; il contratto con il fotografo, che ci cede i diritti delle immagini.", "서류철을 준비했습니다, 원사님. 이탈리아에 등록된 'Corsini 1958' 상표, 'Corsini Scandicci' 국제 출원서, 그리고 사진 권리를 저희에게 넘긴 사진가와의 계약서입니다."),
(CA, "Molto bene. E da quando?", "아주 좋습니다. 그럼 언제부터요?"),
(F, "Da domenica diciotto maggio. Mia figlia l'ha vista online, durante il pranzo. Abbiamo le schermate con la data.", "5월 18일 일요일부터요. 제 딸이 점심 먹다가 인터넷에서 봤어요. 날짜가 찍힌 화면 캡처가 있습니다."),
(CA, "E dopo? Avete fatto qualcosa?", "그 뒤엔요? 뭔가 하셨나요?"),
(F, "Mio fratello l'ha segnalata al sito il lunedì. La pagina è stata tolta il mercoledì. Il giovedì ne è comparsa un'altra, uguale, con un nome diverso.", "제 동생이 월요일에 사이트에 신고했어요. 수요일에 페이지가 내려갔고요. 목요일에 똑같은 페이지가 다른 이름으로 또 올라왔습니다."),
(CA, "Succede sempre così. È come togliere le erbacce senza la radice.", "늘 그래요. 뿌리는 두고 잡초만 뽑는 셈이죠."),
(AM, "Per questo siamo qui, maresciallo. La radice la trovate voi.", "그래서 저희가 여기 온 겁니다, 원사님. 뿌리는 원사님들이 찾으시죠."),
(CA, "Se c'è, la troviamo. Questo è il pacco?", "있다면 찾습니다. 이게 그 상자인가요?"),
(F, "Sì. L'ha ordinato mia figlia, con la carta di mia madre. È arrivato ieri. Non l'abbiamo aperto.", "네. 제 딸이 제 어머니 카드로 주문했어요. 어제 도착했고요. 열지 않았습니다."),
(CA, "Bravi. Lo apriamo adesso, qui, e verbalizzo. Signor Paoli, lei è d'accordo a fare da testimone?", "잘하셨습니다. 지금 여기서 열고, 제가 기록하겠습니다. 파올리 씨, 증인을 서 주시겠어요?"),
(R, "Sono venuto apposta, maresciallo.", "그러려고 왔습니다, 원사님."),
(None, "Cappelli infila un paio di guanti e taglia il nastro adesivo. L'odore arriva prima della borsa: dolciastro, chimico. Renzo chiude gli occhi un istante.", "카펠리가 장갑을 끼고 테이프를 자른다. 가방보다 냄새가 먼저 올라온다. 달큰하고 화학적인 냄새. 렌초가 잠깐 눈을 감는다."),
(R, "Colla. Colla da scarpe, di quella che si usa a caldo.", "본드다. 신발용 본드, 열로 붙이는 그런 거."),
(CA, "Lo sente dall'odore?", "냄새로 아세요?"),
(R, "Maresciallo, io la colla la uso poco, ma la conosco bene. È come un vicino di casa antipatico.", "원사님, 전 본드를 거의 안 쓰지만 아주 잘 압니다. 얄미운 이웃 같은 거죠."),
(None, "La borsa esce dal sacchetto. A prima vista assomiglia alla Domenica: stessa forma, stesso colore miele. Renzo non la tocca ancora. La guarda.", "가방이 봉지에서 나온다. 언뜻 보면 도메니카와 닮았다. 같은 모양, 같은 꿀색. 렌초는 아직 만지지 않는다. 바라보기만 한다."),
(CA, "Allora, signor Paoli? Mi dica quello che vede. Io scrivo.", "자, 파올리 씨? 보이는 걸 말씀해 주세요. 제가 받아 적겠습니다."),
(R, "Primo: non è pelle. È un tessuto plastificato, stampato per sembrare pelle. Si vede dal bordo: dentro è bianco, come un biscotto.", "첫째, 가죽이 아닙니다. 가죽처럼 보이게 찍어 낸 코팅 원단이에요. 가장자리를 보면 알아요. 속이 하얗습니다, 비스킷처럼."),
(CA, "«Materiale sintetico», scrivo così?", "'합성 소재'라고 쓰면 될까요?"),
(R, "Scriva così. Secondo: il bordo non è dipinto. È una striscia di plastica incollata sopra. Il nostro bordo si dipinge a mano, tre passate.", "그렇게 쓰세요. 둘째, 가장자리가 칠한 게 아닙니다. 플라스틱 띠를 위에 붙였어요. 저희 가장자리는 손으로 세 번 칠합니다."),
(CA, "Terzo?", "셋째는요?"),
(R, "Terzo: le cuciture. Sei punti ogni tre centimetri. Noi ne facciamo dieci. E il filo è sintetico, si sfila con un'unghia.", "셋째, 바느질. 3센티에 여섯 땀이에요. 저희는 열 땀을 놓습니다. 그리고 실이 합성이라 손톱으로 당기면 풀려요."),
(F, "E il timbro?", "그럼 도장은?"),
(R, "(la gira, finalmente la tocca) Il timbro... guardi qui, maresciallo. Hanno scritto «Pelletteria V. Corsini». Con la V. Il nonno si chiamava Ugo.", "(마침내 가방을 뒤집어 만지며) 도장은… 여기 보세요, 원사님. 'Pelletteria V. Corsini'라고 썼어요. V로요. 할아버지 이름은 우고였는데."),
(CA, "Hanno copiato da una foto e hanno letto male la U.", "사진을 보고 베끼다가 U를 잘못 읽었군요."),
(AM, "Questo, maresciallo, risulta utile anche a noi: dimostra che il disegno non è loro.", "원사님, 이건 저희에게도 쓸모가 있습니다. 디자인이 그쪽 것이 아니라는 증거니까요."),
(CA, "Certo. E qui dentro? (apre la cerniera) Un'etichetta cucita: «Made in Italy — Vera pelle».", "물론이죠. 그럼 안쪽은요? (지퍼를 연다) 꿰매 붙인 라벨이 있네요. 'Made in Italy — 진짜 가죽'."),
(F, "Due bugie in quattro parole.", "네 단어에 거짓말이 두 개."),
(CA, "Due reati, signor Corsini, se si dimostra. Ma andiamo con ordine. Il pacco da dove arriva?", "입증되면 범죄 두 건이죠, 코르시니 씨. 하지만 순서대로 갑시다. 상자는 어디서 왔습니까?"),
(None, "Mancini gira il cartone. L'etichetta di spedizione è stampata in italiano. Il mittente è una società di logistica con sede in una zona industriale di Prato.", "만치니가 상자를 돌린다. 배송 라벨은 이탈리아어로 인쇄되어 있다. 발송인은 프라토의 한 공단에 소재한 물류 회사다."),
(F, "Prato? Ma il sito diceva «spedizione dall'estero».", "프라토요? 사이트에는 '해외 배송'이라고 돼 있었는데요."),
(CA, "Il sito dice quello che conviene. Un pacco che parte da un magazzino italiano arriva prima e fa meno domande.", "사이트는 자기한테 유리한 말을 하죠. 이탈리아 창고에서 나간 상자는 더 빨리 도착하고, 질문도 덜 받으니까요."),
(R, "Allora le fanno a Prato?", "그럼 프라토에서 만드는 겁니까?"),
(CA, "Questo non l'ho detto, signor Paoli. Un magazzino di logistica non è una fabbrica. Le merci possono arrivare da qualunque parte del mondo in un container, e lì dentro si fanno i pacchi.", "그렇게 말하지 않았습니다, 파올리 씨. 물류 창고는 공장이 아니에요. 물건은 컨테이너에 실려 세계 어디서든 들어올 수 있고, 거기서는 상자를 꾸리는 거죠."),
(AM, "E magari ci si cuce anche un'etichetta.", "그리고 어쩌면 거기서 라벨도 하나 꿰매 붙이고요."),
(CA, "Magari. Lo verificheremo. E le dico subito una cosa, avvocato, perché la sento dire troppo spesso: non si tratta di chi lavora a Prato. Si tratta di chi scrive «Made in Italy» su una cosa che non lo è. Può avere qualunque cognome.", "어쩌면요. 확인하겠습니다. 그리고 변호사님, 너무 자주 듣는 말이라 바로 말씀드리죠. 이건 프라토에서 일하는 사람들의 문제가 아닙니다. 이탈리아산이 아닌 물건에 'Made in Italy'라고 쓰는 사람의 문제죠. 그 사람의 성(姓)은 뭐든 될 수 있습니다."),
(F, "Siamo d'accordo, maresciallo. Noi non accusiamo nessuno. Vogliamo solo che si sappia la verità sulla borsa.", "동의합니다, 원사님. 저흰 누구도 비난하지 않아요. 가방에 관한 진실이 알려지기를 바랄 뿐입니다."),
(CA, "Bene, è l'atteggiamento giusto. Allora faccia in modo che nessuno della sua azienda vada a curiosare in quella zona. Niente telefonate, niente visite, niente post.", "좋습니다, 그게 옳은 태도예요. 그럼 회사 사람 누구도 그 지역에 기웃거리지 않도록 해 주세요. 전화도, 방문도, 게시물도 안 됩니다."),
(F, "Glielo garantisco. Mio fratello e mia figlia sono avvisati.", "보장합니다. 제 동생과 딸에게도 일러뒀어요."),
(CA, "Bene. Adesso la parte noiosa: la denuncia-querela. In quanto legale rappresentante, la firma lei. L'avvocato ha già scritto la bozza?", "좋습니다. 이제 지루한 부분이죠. 고소장입니다. 법정 대리인 자격으로 코르시니 씨가 서명하세요. 변호사님이 초안을 써 오셨나요?"),
(AM, "Eccola. Contraffazione di marchio, uso illecito di immagini, falsa indicazione di origine. Con gli allegati numerati.", "여기 있습니다. 상표 위조, 이미지 무단 사용, 원산지 허위 표시. 첨부 서류에는 번호를 매겼습니다."),
(CA, "(sfoglia) Avvocato, lei è uno di quelli che fanno le cartelle come una volta.", "(넘겨 보며) 변호사님은 옛날식으로 서류철을 만드시는 분이군요."),
(AM, "Sono uno di quelli che hanno perso una causa, nel novantotto, per un allegato senza numero.", "98년에 번호 없는 첨부 서류 하나 때문에 소송을 진 사람이죠."),
(CA, "(sorride) Allora firmi, signor Corsini. Qui, qui e qui.", "(웃으며) 그럼 서명하세요, 코르시니 씨. 여기, 여기, 그리고 여기."),
(None, "Filippo firma tre volte con la penna d'argento del padre. Renzo guarda la borsa finta, poi le proprie mani.", "필리포가 아버지의 은 만년필로 세 번 서명한다. 렌초는 가짜 가방을 보고, 이어서 자기 손을 본다."),
(R, "Maresciallo, una domanda. Questa borsa, dopo, che fine fa?", "원사님, 하나 여쭤도 될까요? 이 가방은 나중에 어떻게 됩니까?"),
(CA, "Resta agli atti, come prova. Alla fine, di solito, si distrugge.", "증거로 보관됩니다. 보통은 결국 폐기되죠."),
(R, "Bene. Perché ha il nome di un uomo che non se lo merita.", "다행입니다. 이건 이런 대접을 받을 이유가 없는 사람의 이름을 달고 있거든요."),
(F, "Quanto tempo ci vorrà, maresciallo?", "얼마나 걸릴까요, 원사님?"),
(CA, "Non glielo so dire. Man mano che troviamo le carte, andiamo avanti. Ma un indirizzo stampato su un pacco, di solito, accorcia molto la strada.", "말씀드릴 수 없습니다. 서류를 찾는 대로 하나씩 나아가니까요. 하지만 상자에 인쇄된 주소 하나가 보통은 길을 많이 줄여 줍니다."),
(AM, "Grazie, maresciallo.", "감사합니다, 원사님."),
(CA, "Grazie a voi. Di solito le aziende vengono quando i pezzi venduti sono diecimila. Voi siete venuti a duecento. È più facile così.", "제가 감사하죠. 보통 회사들은 만 개가 팔린 뒤에야 옵니다. 여러분은 200개에서 오셨어요. 이게 훨씬 수월합니다."),
(None, "Sulle scale della caserma, Mancini si abbottona la giacca anche se è maggio.", "본부 계단에서 만치니가 5월인데도 재킷 단추를 채운다."),
(AM, "Filippo, una cosa. Da oggi la parte più difficile non è la Finanza. È la pazienza.", "필리포, 하나만. 오늘부터 제일 어려운 건 재무경찰이 아니야. 인내심이지."),
(F, "La pazienza la conosco. Ho diciannove anni di Maison alle spalle.", "인내심이라면 알아요. 메종하고 19년을 일했는걸요."),
(AM, "Allora sai che la tentazione più grande è parlare. Tuo fratello vorrà raccontarlo dappertutto.", "그럼 제일 큰 유혹이 말하는 거라는 것도 알겠지. 네 동생은 여기저기 다 얘기하고 싶어 할 거다."),
(F, "Mio fratello vorrà raccontarlo in coreano.", "제 동생은 한국어로 얘기하고 싶어 할걸요."),
(AM, "(ride) Che lo racconti pure in coreano, purché non faccia nomi.", "(웃으며) 한국어로 하든 말든, 이름만 대지 않으면 돼."),
(R, "Avvocato, quella V... non me la tolgo dalla testa. Settant'anni di laboratorio, e ci rubano il nome con una lettera sbagliata.", "변호사님, 그 V가… 머리에서 안 떠나요. 70년 공방인데, 철자 하나 틀린 걸로 우리 이름을 훔쳐 가다니."),
(AM, "Non ve l'hanno rubato, Renzo. Hanno firmato la loro confessione. Con una V.", "훔쳐 간 게 아니에요, 렌초. 그들이 자백서에 서명한 거죠. V로."),
(R, "Questa la racconto al bar.", "그 얘긴 바에 가서 해야겠네."),
(F, "Al bar no, Renzo. Te l'ha appena detto il maresciallo.", "바에서는 안 돼, 렌초. 원사님이 방금 말했잖아."),
(R, "Al bar racconto solo la V. Il resto me lo tengo.", "바에선 V 얘기만 할게. 나머지는 내가 간직하고."),

("#", "Scena 3 — Venerdì 30 maggio, ore 18.10. L'ufficio di Filippo, Scandicci.", "장면 3 — 5월 30일 금요일 오후 6시 10분. 스칸디치, 필리포의 사무실."),
(None, "Il laboratorio si sta svuotando. Lorenzo è seduto davanti alla scrivania di Filippo con un foglio solo, come ogni volta. Matteo entra senza bussare, il telefono in mano.", "공방이 비어 간다. 로렌초는 늘 그렇듯 종이 한 장만 들고 필리포의 책상 앞에 앉아 있다. 마테오가 휴대폰을 손에 든 채 노크도 없이 들어온다."),
(M, "Avete visto il sito? In due giorni, quarantuno ordini. Quarantuno, Filippo. In tutto aprile ne avevamo fatti trentadue.", "사이트 봤어? 이틀 만에 주문이 41건이야. 41건이라고, 형. 4월 한 달 동안 32건이었는데."),
(L, "E nessuno ha chiesto lo sconto. Li ho guardati uno per uno.", "그리고 아무도 할인을 요구하지 않았어. 하나하나 다 봤어."),
(F, "Da dove arrivano?", "어디서 온 주문이야?"),
(M, "Da Nora. Ha scritto il nostro comunicato, quello delle tre frasi, e un giornale di Firenze l'ha ripreso. «Le uniche che non sono riusciti a copiare: le mani di Renzo.»", "노라 덕분이야. 세 문장짜리 우리 성명서를 피렌체의 한 신문이 받아서 실었어. '그들이 베끼지 못한 유일한 것, 렌초의 손.'"),
(F, "Renzo aveva detto «non sul giornale».", "렌초는 '신문엔 내지 말라'고 했잖아."),
(M, "L'ha letto stamattina al bar. Ha detto: «Almeno hanno scritto giusto il cognome».", "오늘 아침에 바에서 읽었대. '그래도 성은 제대로 썼구먼' 하더라."),
(L, "Il che, per Renzo, è un sì.", "그건 렌초식으로 '좋다'는 뜻이지."),
(None, "Squilla il telefono fisso. Filippo risponde. È il maresciallo Cappelli.", "유선 전화가 울린다. 필리포가 받는다. 카펠리 원사다."),
(CA, "Signor Corsini? Cappelli. Le telefono perché domani lo leggerà sui giornali, e preferisco che lo sappia da me.", "코르시니 씨? 카펠리입니다. 내일 신문에서 읽으시게 될 테니, 저한테서 먼저 들으시는 게 좋겠다 싶어 전화드렸습니다."),
(F, "Mi dica.", "말씀하세요."),
(CA, "Stamattina abbiamo fatto un controllo nel magazzino dell'etichetta. Abbiamo sequestrato milleottocento pezzi. Borse, portafogli e cinture, con il vostro nome e con quello di altri sei marchi.", "오늘 아침 그 라벨에 적힌 창고를 점검했습니다. 1,800점을 압수했어요. 가방, 지갑, 벨트입니다. 여러분 이름과 다른 브랜드 여섯 곳의 이름이 붙어 있었습니다."),
(F, "Milleottocento.", "1,800점이라니."),
(CA, "Risulta che la merce entrava in container, dichiarata come accessori generici in materiale sintetico. Le etichette «Made in Italy» venivano cucite qui, nel magazzino, prima di spedire i pacchi.", "물건은 컨테이너로 들어왔고, 합성 소재 일반 잡화로 신고됐던 것으로 확인됩니다. 'Made in Italy' 라벨은 상자를 발송하기 전에 여기, 창고 안에서 꿰매 붙였고요."),
(F, "E chi...?", "그럼 누가…?"),
(CA, "Un intermediario italiano, titolare della società di logistica. È indagato. Più di questo non posso dirle, e le chiedo di non scriverlo da nessuna parte.", "물류 회사 대표인 이탈리아인 중개업자입니다. 수사 대상이에요. 그 이상은 말씀드릴 수 없고, 어디에도 쓰지 말아 주셨으면 합니다."),
(F, "Non lo scriverò. Grazie, maresciallo. Davvero.", "쓰지 않겠습니다. 감사합니다, 원사님. 정말로요."),
(CA, "Anche il sito, nel frattempo, ha tolto tutti gli annunci collegati. Dica al signor Paoli che la sua «V» ci ha aiutato. Era su tutti i pezzi.", "그사이 사이트도 관련 게시물을 모두 내렸습니다. 파올리 씨께 그 'V'가 도움이 됐다고 전해 주세요. 모든 물건에 찍혀 있었거든요."),
(None, "Filippo riaggancia. Per qualche secondo nessuno parla.", "필리포가 전화를 끊는다. 몇 초 동안 아무도 말하지 않는다."),
(M, "Allora?", "그래서?"),
(F, "Milleottocento pezzi sequestrati. Il sito ha tolto tutto. E il nonno, in questa storia, si chiamava Vgo.", "1,800점 압수. 사이트는 전부 내렸고. 그리고 이 이야기에서 할아버지 이름은 '브고'였대."),
(M, "(ride, poi si ferma) Milleottocento. Se ne avessero vendute milleottocento...", "(웃다가 멈추며) 1,800개라. 그걸 다 팔았다면…"),
(L, "Non pensarci. Pensa ai quarantuno veri.", "생각하지 마. 진짜 41건을 생각해."),
(M, "Ai quarantuno veri, e a una cosa che mi ha scritto Kim stamattina.", "진짜 41건이랑, 오늘 아침에 김 차장님이 보낸 얘기도."),
(F, "Cioè?", "뭔데?"),
(M, "A Seul, dopo la nostra lettera in coreano, nessuno ha più chiesto lo sconto. E due clienti hanno chiesto se le borse si possono riparare, fra dieci anni.", "서울에선 우리 한국어 편지 이후로 할인 요구가 한 건도 없대. 그리고 고객 두 명이 10년 뒤에 가방을 수선할 수 있냐고 물었대."),
(L, "Riparare. Questa è una domanda da clienti veri.", "수선이라. 그건 진짜 고객이 하는 질문이지."),
(F, "E tu cosa le hai risposto?", "그래서 넌 뭐라고 답했어?"),
(M, "Che Renzo ripara ancora le borse del nonno. E che quando Renzo non ci sarà più, ci sarà Simone.", "렌초가 아직도 할아버지 시절 가방을 고친다고. 그리고 렌초가 없게 되면 시모네가 있다고."),
(F, "Non dire «quando Renzo non ci sarà più». Porta male.", "'렌초가 없게 되면'이라고 하지 마. 재수 없어."),
(M, "Hai ragione. Le ho scritto «fra moltissimi anni».", "맞아. '아주아주 먼 훗날'이라고 썼어."),
(L, "Filippo, posso aggiungere una riga al foglio di lunedì? Una sola.", "필리포, 월요일 보고서에 한 줄만 더 넣어도 돼? 딱 한 줄."),
(F, "Quale?", "뭔데?"),
(L, "«Spese legali: nessuna fattura dell'avvocato, per ora.» Così, quando arriva, nessuno si spaventa.", "'법률 비용: 아직 변호사 청구서 없음.' 그래야 나중에 청구서가 와도 아무도 놀라지 않지."),
(M, "E metti anche i quarantuno ordini, Lorenzo. In grassetto.", "그리고 주문 41건도 넣어 줘, 로렌초. 굵은 글씨로."),
(F, "Lorenzo, mettilo nel foglio di lunedì. Una riga: «Contraffazione: denuncia, sequestro, quarantuno ordini». Senza aggettivi.", "로렌초, 월요일 보고서에 넣어 줘. 한 줄로. '위조품: 고소, 압수, 주문 41건.' 형용사 없이."),
(L, "Senza aggettivi. (si alza) E tu vai a casa, Filippo. Hai la faccia di uno che non dorme da una settimana.", "형용사 없이. (일어서며) 그리고 넌 집에 가, 필리포. 일주일 동안 못 잔 사람 얼굴이야."),
(F, "Fra dieci minuti.", "10분 뒤에."),
(None, "Lorenzo e Matteo escono. Filippo resta solo. Il cellulare vibra di nuovo: lo stesso numero francese di martedì. Questa volta Filippo risponde.", "로렌초와 마테오가 나간다. 필리포 혼자 남는다. 휴대폰이 다시 진동한다. 화요일과 같은 프랑스 번호. 이번에는 필리포가 받는다."),
(F, "Allô, Hélène.", "알로, 엘렌."),
(HE, "Filippo, finalmente. Ho letto la storia della borsa falsa. Complimenti per la denuncia: avete fatto le cose per bene.", "필리포, 드디어 받네요. 가짜 가방 이야기 읽었어요. 고소한 거 잘했어요. 일을 제대로 처리했네요."),
(F, "Grazie. Martedì non potevo rispondere. Ero dalla Finanza.", "고마워요. 화요일엔 받을 수가 없었어요. 재무경찰에 가 있었거든요."),
(HE, "Lo immaginavo. Non ti chiamavo per la borsa, però. Ti chiamavo per un'altra cosa, e non è una cosa da telefono.", "그럴 줄 알았어요. 그런데 가방 때문에 전화한 건 아니에요. 다른 일 때문인데, 전화로 할 얘기는 아니에요."),
(F, "Che cosa?", "뭔데요?"),
(HE, "Dopo l'estate. Passo da Firenze. Parliamo da persone che si conoscono da diciannove anni.", "여름 지나고요. 피렌체에 들를게요. 19년 지기답게 얘기해요."),
(F, "Hélène, se è una cosa della Maison, devo saperlo adesso. Ho una famiglia, qui, che vuole sapere tutto.", "엘렌, 메종 일이라면 지금 알아야 해요. 여기 모든 걸 알고 싶어 하는 가족이 있다고요."),
(HE, "Proprio per questo te lo dirò di persona. Buona serata, Filippo. E riposati: hai una voce terribile.", "그러니까 직접 말할게요. 좋은 저녁 보내요, 필리포. 그리고 좀 쉬어요. 목소리가 엉망이에요."),
(None, "Filippo posa il telefono sulla scrivania, accanto alla cartella di Mancini. Sulla copertina, scritto con la sua calligrafia: «Prova n. 1 — borsa falsa». Spegne la luce.", "필리포가 만치니의 서류철 옆 책상 위에 휴대폰을 내려놓는다. 표지에는 그의 글씨로 '증거 1번 — 가짜 가방'. 그가 불을 끈다."),
]

